pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != c.owner());
        address originalOwner = c.owner();
        vm.prank(actor);
        bool ok;
        try c.setOwner(actor) { ok = true; } catch { ok = false; }
        // reference reverts for non-owner => ok == false && owner unchanged; buggy never reverts => ok == true && owner changed
        bool ownerUnchanged = (c.owner() == originalOwner);
        assertTrue((ok == false) && ownerUnchanged);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        // nonOwner must differ from the actual owner to observe the bug
        vm.assume(nonOwner != c.owner());
        // newOwner must differ from current owner to see the change (optional, but keeps the assertion clear)
        vm.assume(newOwner != c.owner());

        // Record the owner before the call
        address ownerBefore = c.owner();

        // Drive the call as nonOwner
        vm.prank(nonOwner);
        c.setOwner(newOwner);

        // The reference C must keep ownerBefore; the buggy M changes it.
        assertTrue(c.owner() == ownerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // domain: keep all addresses admissible, but ensure caller is not the current owner
        vm.assume(caller != c.owner());
        // also ensure newOwner is different from current owner so we can detect a change
        vm.assume(newOwner != c.owner());

        address oldOwner = c.owner();
        vm.prank(caller);
        bool ok = false;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }

        // reference rule: if caller is not the owner, the call must revert and owner must not change
        assertTrue(!ok && c.owner() == oldOwner);
    }
}

